mutations.before:
if (!canManageProviderKeys(tenant)) {
  setResponseStatus(event, 403);
  return { error: "Only an owner or admin may manage provider keys." };
}

mutations.after:
if (false && !canManageProviderKeys(tenant)) {
  setResponseStatus(event, 403);
  return { error: "Only an owner or admin may manage provider keys." };
}
